"use strict";(globalThis.webpackChunkgrc||=[]).push([[49379],{46833(e){e.exports=JSON.parse('[{"citeKey":"tang2026dataflow","slug":"tang-2026-dataflow-workflow-b4e1","title":"Characterizing Dataflow for I/O-Aware Scheduling in HPC Workflows","authors":["M. Tang","L. Guo","A. Kougkas","X.-H. Sun","N. R. Tallent"],"venue":"40th IEEE International Parallel and Distributed Processing Symposium (IPDPS 2026)","type":"Conference","entryType":"inproceedings","date":"May, 2026","year":2026,"era":"iit","month":5,"doi":"10.1109/IPDPS65963.2026.00076","abstract":"Scientific discoveries are increasingly facilitated by data-driven workflows executed in HPC environments, where complex task-to-data exchange patterns cause bottlenecks in shared storage. Existing I/O-aware scheduling techniques use application-oriented metrics that primarily focus on individual task characteristics, leaving workflow-level dataflow behaviors\u2014such as file reuse and producer\u2013consumer I/O patterns\u2014underexplored despite their importance for effective orchestration. This paper presents a workflow-centric methodology to characterize and analyze I/O using workflow-specific patterns and metrics. By correlating workflow structures (e.g., task composition, execution order, and producer\u2013consumer relationships) with I/O metrics (e.g., access type, operation count, and data size), we gain deeper insight into workflow I/O dynamics. We evaluate our approach on six diverse HPC workflows, covering 3,500 task instances and 1,387 unique files, with a total I/O volume of 1.5 TB. This analysis uncovers a spectrum of behaviors related to file reuse, data exchange, and task-level I/O heterogeneity. These insights reveal new opportunities and research directions for I/O-aware scheduling, supporting smarter task placement, data movement, and storage selection in HPC.","hasAbstract":true,"lede":"This paper presents a workflow-centric methodology to characterize and analyze I/O using workflow-specific patterns and metrics.","pages":"868\u2013884","links":{"pdf":"https://grc.iit.edu/papers/2026/tang-2026-dataflow-workflow-b4e1.pdf","bibtex":"https://grc.iit.edu/papers/2026/tang-2026-dataflow-workflow-b4e1-bibtex.bib","citation":"https://grc.iit.edu/papers/2026/tang-2026-dataflow-workflow-b4e1-citation.txt"},"tags":["HPC Analysis","I/O","Workflow Optimization","Data Analytics","Performance Measurement"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"PNNL","award":"DE-AC05-76RL01830","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"tang2026storagemismatches","slug":"tang-2026-storage-mismatches-7f3d","title":"The Hidden Cost of Storage Mismatches: Why Faster I/O Per Task Can Slow Down Entire Workflows","authors":["M. Tang","L. Guo","N. R. Tallent","A. Kougkas","X.-H. Sun"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"abstract":"Data-intensive scientific workflows in high-performance computing exchange intermediate data between pipeline stages through shared storage such as parallel file systems, local SSDs, and burst buffers. Existing workflow schedulers select storage to maximize individual task throughput, implicitly assuming that faster I/O per task yields faster end-to-end execution. We show this assumption is wrong. We present an empirical study across two scientific workflows\u2014genomics and climate tracking\u2014on a production HPC cluster. By benchmarking storage systems across operation types, transfer sizes, parallelism levels, and data volumes, we uncover two non-obvious findings. First, data movement between storage tiers scales fundamentally differently from read and write operations: copy throughput plateaus or degrades at parallelism levels where reads and writes continue to scale, making cross-tier staging costs unpredictable from standard I/O benchmarks. Second, producer-consumer task pairs can exhibit performance inversion\u2014configurations that maximize throughput for individual tasks introduce costly inter-stage data movement that increases total workflow time by up to 6.8x compared to storage-aware alternatives. Across both workflows, I/O accounts for 42\u201398% of total execution time, yet the penalty from storage mismatches between dependent tasks can exceed the compute cost of the tasks themselves. These patterns hold across fundamentally different access profiles, from large sequential transfers to metadata-heavy many-small-file workloads. Our results demonstrate that producer-consumer data dependencies must be treated as first-class constraints in workflow scheduling.","hasAbstract":true,"lede":"We present an empirical study across two scientific workflows, genomics and climate tracking, on a production HPC cluster.","links":{"poster":"https://grc.iit.edu/papers/2026/tang-2026-storage-mismatches-7f3d-poster.pdf","bibtex":"https://grc.iit.edu/papers/2026/tang-2026-storage-mismatches-7f3d-bibtex.bib","citation":"https://grc.iit.edu/papers/2026/tang-2026-storage-mismatches-7f3d-citation.txt"},"tags":["HPC Analysis","I/O","Workflow Optimization","Data Analytics","Performance Measurement"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"tallent2026dataflowdrs","slug":"tallent-2026-dataflowdrs-5e21","title":"DataFlowDrs: Automating Performance Optimization of Data Flow Within HPC Workflows","authors":["N. R. Tallent","M. Tang","J. Firoz","Z. Peng","L. Guo","A. Kougkas","X.-H. Sun"],"venue":"IEEE Transactions on Parallel and Distributed Systems","type":"Journal","entryType":"article","date":"2026","year":2026,"era":"iit","doi":"10.1109/TPDS.2026.3722592","hasAbstract":false,"pages":"1\u201318","_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"tang2025s3roofline","slug":"tang-2025-s3-roofline-c7bd","title":"Quantifying AWS S3 I/O Performance Boundaries Using the Roofline Model","authors":["M. Tang","Z. Zhu","L. Guo","J. G. Bandy","T. Carlson","S. Neuwirth","A. Kougkas","X.-H. Sun","N. R. Tallent"],"venue":"10th International Parallel Data Systems Workshop (PDSW 2025), Proceedings of the SC \'25 Workshops","type":"Workshop","entryType":"inproceedings","date":"November, 2025","year":2025,"era":"iit","month":11,"doi":"10.1145/3731599.3767513","abstract":"High-performance computing facilities increasingly form hybrid environments that integrate cloud services. To avoid cumbersome network transfers when sharing data, a new class of storage gateways map a subset of facility storage to a cloud counterpart and automatically manage data mirroring. However, the performance characteristics of accessing AWS\'s S3 from HPC systems using different methods and patterns remains poorly understood. This paper presents a roofline-based analysis of three S3 integration approaches: NFS-mounted AWS Storage Gateway, data migration through Storage Gateway, and direct S3 API transfers. We extend I/O roofline modeling to characterize operational intensity and bandwidth ceilings across varying data sizes and access patterns. Our experimental evaluation demonstrates significant performance differences between access methods, with POSIX I/O on NFS Storage Gateway achieving up to 6.4\xd7 higher bandwidth than other approaches for large transfers. The roofline analysis reveals distinct characteristics for each method, enabling informed selection of S3 integration strategies.","hasAbstract":true,"pages":"1415\u20131423","links":{"pdf":"https://grc.iit.edu/papers/2025/tang-2025-s3-roofline-c7bd.pdf"},"tags":["I/O","Cloud Storage","AWS S3","Roofline Model","Performance Analysis"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"PNNL","award":"DE-AC05-76RL01830","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"tang2025ioworkflows","slug":"tang-2025-ioworkflows-a9f3","title":"Analyzing I/O Patterns and Dataflow in HPC Workflows","authors":["M. Tang","L. Guo","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"The 37h International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Technical Report","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2025/tang-2025-ioworkflows-a9f3-poster.pdf"},"tags":["HPC Analysis","I/O","Workflow Optimization","Data Analytics","Performance Measurement"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"tang2024dayu","slug":"tang-2024-dayu-f286","title":"DaYu: Optimizing Distributed Scientific Workflows by Decoding Dataflow Semantics and Dynamics","authors":["M. Tang","J. Cernuda","J. Ye","L. Guo","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"2024 IEEE International Conference on Cluster Computing (CLUSTER\'24)","type":"Conference","entryType":"inproceedings","date":"September, 2024","year":2024,"era":"iit","month":9,"doi":"10.1109/cluster59578.2024.00038","abstract":"The combination of ever-growing scientific datasets and distributed workflow complexity creates I/O performance bottlenecks due to data volume, velocity, and variety. Although the increasing use of descriptive data formats (e.g., HDF5, netCDF) helps organize these datasets, it also introduces obscure bottlenecks due to the need to translate high-level operations into file addresses and then into low-level I/O operations. To address this challenge, we introduce DaYu, a method and toolset for analyzing (a) semantic relationships between logical datasets and file addresses, (b) how dataset operations translate into I/O, and (c) the combination across entire workflows. DaYu\'s analysis and visualization enable the identification of critical bottlenecks and the reasoning about remediation. We describe our methodology and propose optimization guidelines. Evaluation on scientific workflows demonstrates up to a 3.7x performance improvement in I/O time for obscure bottlenecks. The time and storage overhead for DaYu\'s time-ordered data are typically under 0.2% of runtime and 0.25% of data volume, respectively.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/tang-2024-dayu-f286.pdf"},"tags":["Data Analytics","Modeling","Performance Measurement","Tools","Workflow Optimization"],"_projectIds":["portus"],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"lee2023datalifecycles","slug":"lee-2023-data-lifecycles-c393","title":"Data Flow Lifecycles for Optimizing Workflow Coordination","authors":["H. Lee","L. Guo","M. Tang","J. Firoz","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'23), November 12-17, 2023","type":"Conference","entryType":"inproceedings","date":"November, 2023","year":2023,"era":"iit","month":11,"doi":"10.1145/3581784.3607104","abstract":"A critical performance challenge in distributed scientific workflows is coordinating tasks and data flows on distributed resources. To guide these decisions, this paper introduces data flow lifecycle anal- ysis. Workflows are commonly represented using directed acyclic graphs (DAGs). Data flow lifecycles (DFL) enrich task DAGs with data objects and properties that describe data flow and how tasks interact with that flow. Lifecycles enable analysis from several important perspectives: task, data, and data flow. We describe rep- resentation, measurement, analysis, visualization, and opportunity identification for DFLs. Our measurement is both distributed and scalable, using space that is constant per data file. We use lifecycles and opportunity analysis to reason about improved task placement and reduced data movement for five scientific workflows with dif- ferent characteristics. Case studies show improvements of 15x, 1.9\xd7, and 10-30x. Our work is implemented in the DataLife tool.","hasAbstract":true,"lede":"To guide these decisions, this paper introduces data flow lifecycle anal- ysis.","pages":"1\u201315","links":{"pdf":"https://grc.iit.edu/papers/2023/lee-2023-data-lifecycles-c393.pdf"},"tags":["Data Analytics","Performance Measurement","Modeling","Tools"],"_projectIds":[],"_funding":[{"agency":"PNNL","award":"DE-AC05-76RL01830","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"}]')}}]);